import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 알림 채널은 기본 채널인 포털로 한다.
const NOTIFY_CHANNEL = '포털';
const STATUSES = ['신청', '승인', '반려'];

// 가정: 변경 항목 이름과 인사기록카드 컬럼의 대응. 이 항목만 신청할 수 있다.
const SELECT_BY_ITEM: Record<string, string> = {
  '주소': 'SELECT personnel_record_id AS "recordId", address_enc AS "value" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
  '보훈 정보': 'SELECT personnel_record_id AS "recordId", veteran_info AS "value" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
  '병역 정보': 'SELECT personnel_record_id AS "recordId", military_service_info AS "value" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
  '채용 구분': 'SELECT personnel_record_id AS "recordId", recruitment_type AS "value" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
  '채용 정보 비고': 'SELECT personnel_record_id AS "recordId", recruitment_note AS "value" FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
};
const UPDATE_BY_ITEM: Record<string, string> = {
  '주소': 'UPDATE personnel_record SET address_enc = :value, updated_at = now() WHERE personnel_record_id = CAST(:recordId AS bigint)',
  '보훈 정보': 'UPDATE personnel_record SET veteran_info = :value, updated_at = now() WHERE personnel_record_id = CAST(:recordId AS bigint)',
  '병역 정보': 'UPDATE personnel_record SET military_service_info = :value, updated_at = now() WHERE personnel_record_id = CAST(:recordId AS bigint)',
  '채용 구분': 'UPDATE personnel_record SET recruitment_type = :value, updated_at = now() WHERE personnel_record_id = CAST(:recordId AS bigint)',
  '채용 정보 비고': 'UPDATE personnel_record SET recruitment_note = :value, updated_at = now() WHERE personnel_record_id = CAST(:recordId AS bigint)',
};

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function isDigits(v: string): boolean {
  return /^[0-9]+$/.test(v);
}

@Controller('api/v1')
export class FnSfr01202Controller {
  @Get('/personnel-change-requests')
  async listPersonnelChangeRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '임직원');
    let isHr = true;
    try {
      user.require('인사 담당자');
    } catch (e) {
      isHr = false;
    }
    const q = checks.queryOf(req.query);
    const status = text(q['status']);
    if (status !== '' && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 처리 상태 값이 올바르지 않습니다.');
    }
    const employeeIdText = text(String(q['employeeId'] ?? ''));
    if (employeeIdText !== '' && !isDigits(employeeIdText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 임직원 값이 올바르지 않습니다.');
    }
    const pageText = text(String(q['page'] ?? '0'));
    const sizeText = text(String(q['size'] ?? '20'));
    if (!isDigits(pageText) || !isDigits(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    // 임직원은 본인 신청만 본다.
    const employeeId = isHr ? (employeeIdText === '' ? null : employeeIdText) : user.id;
    return transaction(async (db) => {
      const params = {
        status: status === '' ? null : status,
        employeeId,
        size,
        offset: page * size,
      };
      const where = ' WHERE (CAST(:status AS text) IS NULL OR status = CAST(:status AS text)) AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))';
      const items = await db.query(
        'SELECT personnel_change_request_id AS "personnelChangeRequestId", employee_id AS "employeeId", change_item AS "changeItem", before_value_enc AS "beforeValue", after_value_enc AS "afterValue", request_reason AS "requestReason", status AS "status", reject_reason AS "rejectReason" FROM personnel_change_request' + where + ' ORDER BY personnel_change_request_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        params,
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM personnel_change_request' + where,
        { status: params.status, employeeId: params.employeeId },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/personnel-change-requests')
  @HttpCode(200)
  async createPersonnelChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const changeItem = text(data['changeItem']);
    const afterValue = text(data['afterValue']);
    const requestReason = text(data['requestReason']);
    if (changeItem === '' || changeItem.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 항목을 올바르게 입력해 주세요.');
    }
    if (!Object.keys(SELECT_BY_ITEM).includes(changeItem)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청할 수 없는 변경 항목입니다.');
    }
    if (afterValue === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 후 값을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const records = await db.query(SELECT_BY_ITEM[changeItem], { employeeId: user.id });
      if (records.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '인사기록카드를 찾을 수 없습니다.');
      }
      const before = records[0]['value'];
      const inserted = await db.query(
        'INSERT INTO personnel_change_request (employee_id, change_item, before_value_enc, after_value_enc, request_reason, status, created_at, updated_at) VALUES (CAST(:userId AS bigint), :changeItem, :beforeValue, :afterValue, :requestReason, :status, now(), now()) RETURNING personnel_change_request_id AS "personnelChangeRequestId", status AS "status"',
        {
          userId: user.id,
          changeItem,
          beforeValue: before === undefined ? null : before,
          afterValue,
          requestReason: requestReason === '' ? null : requestReason,
          status: '신청',
        },
      );
      return inserted[0];
    });
  }

  @Post('/personnel-change-requests/:personnelChangeRequestId/review')
  @HttpCode(200)
  async reviewPersonnelChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const requestId = req.params['personnelChangeRequestId'];
    if (!isDigits(requestId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 번호가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const status = text(data['status']);
    const rejectReason = text(data['rejectReason']);
    if (status !== '승인' && status !== '반려') {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 또는 반려를 선택해 주세요.');
    }
    if (status === '반려' && rejectReason === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT employee_id AS "employeeId", change_item AS "changeItem", before_value_enc AS "beforeValue", after_value_enc AS "afterValue", status AS "status" FROM personnel_change_request WHERE personnel_change_request_id = CAST(:requestId AS bigint) FOR UPDATE',
        { requestId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PERSONNEL_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      const row = found[0];
      if (row['status'] !== '신청') {
        throw new ApiError(409, 'PERSONNEL_CHANGE_REQUEST_ALREADY_PROCESSED', '이미 ' + String(row['status']) + ' 처리된 신청 건입니다.');
      }
      let appliedRecordId: number | null = null;
      if (status === '승인') {
        const selectSql = SELECT_BY_ITEM[String(row['changeItem'])];
        const updateSql = UPDATE_BY_ITEM[String(row['changeItem'])];
        if (selectSql === undefined || updateSql === undefined) {
          throw new ApiError(400, 'VALIDATION_FAILED', '반영할 수 없는 변경 항목입니다.');
        }
        const records = await db.query(selectSql, { employeeId: String(row['employeeId']) });
        if (records.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '인사기록카드를 찾을 수 없습니다.');
        }
        appliedRecordId = Number(records[0]['recordId']);
        await db.execute(updateSql, { value: row['afterValue'], recordId: appliedRecordId });
        // 가정: 변경 이력 내용은 변경 항목과 변경 전후 값을 그대로 적는다.
        const content = '변경 항목: ' + String(row['changeItem']) + ' / 변경 전: ' + String(row['beforeValue'] ?? '') + ' / 변경 후: ' + String(row['afterValue']);
        await db.execute(
          'INSERT INTO change_history (changer_id, target_type, target_id, changed_at, change_content, created_at, updated_at) VALUES (CAST(:userId AS bigint), :targetType, CAST(:targetId AS bigint), now(), :content, now(), now())',
          { userId: user.id, targetType: 'personnel_record', targetId: appliedRecordId, content },
        );
      }
      const updated = await db.query(
        'UPDATE personnel_change_request SET status = :status, reviewer_id = CAST(:userId AS bigint), reviewed_at = now(), reject_reason = :rejectReason, updated_at = now() WHERE personnel_change_request_id = CAST(:requestId AS bigint) RETURNING status AS "status", reviewed_at AS "reviewedAt", reject_reason AS "rejectReason"',
        { status, userId: user.id, rejectReason: status === '반려' ? rejectReason : null, requestId },
      );
      // 가정: 처리 결과(승인/반려) 안내 알림을 신청자에게 보낸다.
      const title = status === '승인' ? '인사정보 변경 신청이 승인되었습니다.' : '인사정보 변경 신청이 반려되었습니다.';
      const content = status === '승인' ? String(row['changeItem']) + ' 변경이 인사기록카드에 반영되었습니다.' : '반려 사유: ' + rejectReason;
      await db.execute(
        'INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at) VALUES (CAST(:recipientId AS bigint), :channel, :title, :content, :readStatus, :eventType, :targetType, CAST(:targetId AS bigint), now(), now())',
        {
          recipientId: String(row['employeeId']),
          channel: NOTIFY_CHANNEL,
          title,
          content,
          readStatus: '안읽음',
          eventType: 'PERSONNEL_CHANGE_REVIEW',
          targetType: 'PERSONNEL_CHANGE_REQUEST',
          targetId: requestId,
        },
      );
      return {
        status: updated[0]['status'],
        reviewedAt: updated[0]['reviewedAt'],
        rejectReason: updated[0]['rejectReason'],
        appliedPersonnelRecordId: appliedRecordId,
      };
    });
  }
}

