import { useState } from 'react';
import { call, useData, Badge, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field, TextInput, Select, LookupSelect, RefName } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [['신청', '신청'], ['승인', '승인'], ['반려', '반려']];
const CHANGE_ITEMS: [string, string][] = [
  ['주소', '주소'],
  ['보훈 정보', '보훈 정보'],
  ['병역 정보', '병역 정보'],
  ['채용 구분', '채용 구분'],
  ['채용 정보 비고', '채용 정보 비고'],
];

function CreateDrawer({ role, notify, onClose, onDone }: { role: string; notify: (text: string) => void; onClose: () => void; onDone: () => void }) {
  const [changeItem, setChangeItem] = useState('');
  const [afterValue, setAfterValue] = useState('');
  const [requestReason, setRequestReason] = useState('');
  return (
    <Drawer title="인사정보 변경 신청" onClose={onClose}>
      <Form
        submit="신청하기"
        onSubmit={async () => {
          if (changeItem === '') throw new Error('변경 항목을 선택해 주세요.');
          if (afterValue.trim() === '') throw new Error('변경 후 값을 입력해 주세요.');
          await call('POST', '/personnel-change-requests', role, { changeItem, afterValue, requestReason });
          notify('변경 신청을 등록했습니다.');
          onDone();
        }}
      >
        <Field label="변경 항목" required>
          <Select value={changeItem} onChange={setChangeItem} options={CHANGE_ITEMS} />
        </Field>
        <Field label="변경 후 값(암호화)" required wide>
          <TextInput value={afterValue} onChange={setAfterValue} multiline />
        </Field>
        <Field label="신청 사유" wide>
          <TextInput value={requestReason} onChange={setRequestReason} multiline />
        </Field>
      </Form>
    </Drawer>
  );
}

function ReviewForm({ role, notify, requestId, onDone }: { role: string; notify: (text: string) => void; requestId: unknown; onDone: () => void }) {
  const [status, setStatus] = useState('');
  const [rejectReason, setRejectReason] = useState('');
  return (
    <Form
      submit="처리하기"
      note="처리한 뒤에는 다시 검토할 수 없고, 신청자에게 결과가 알림으로 전달됩니다."
      onSubmit={async () => {
        if (status === '') throw new Error('승인 또는 반려를 선택해 주세요.');
        if (status === '반려' && rejectReason.trim() === '') throw new Error('반려 사유를 입력해 주세요.');
        await call('POST', '/personnel-change-requests/' + String(requestId) + '/review', role, { status, rejectReason });
        notify(status === '승인' ? '승인했습니다.' : '반려했습니다.');
        onDone();
      }}
    >
      <Field label="승인 처리 상태" required>
        <Select value={status} onChange={setStatus} options={[['승인', '승인'], ['반려', '반려']]} />
      </Field>
      <Field label="반려 사유" hint="반려할 때 반드시 입력합니다." wide>
        <TextInput value={rejectReason} onChange={setRejectReason} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr01202Page({ role, notify }: PageProps) {
  const isHr = role === '인사 담당자';
  const [draft, setDraft] = useState<{ status: string; employeeId: number | string }>({ status: '', employeeId: '' });
  const [query, setQuery] = useState<{ status: string; employeeId: number | string }>({ status: '', employeeId: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const list = useData<Page>(
    () => call<Page>('GET', '/personnel-change-requests', role, undefined, { status: query.status, employeeId: query.employeeId, page, size: 20 }),
    [role, query, page],
  );

  if (selected) {
    const status = String(selected['status']);
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로</button>
        <section className="box">
          <h2>신청 내용</h2>
          <Pairs
            items={[
              ['신청 임직원', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['변경 항목', String(selected['changeItem'])],
              ['변경 전 값(암호화)', String(selected['beforeValue'] ?? '')],
              ['변경 후 값(암호화)', String(selected['afterValue'] ?? '')],
              ['신청 사유', String(selected['requestReason'] ?? '')],
              ['승인 처리 상태', <Badge value={selected['status']} />],
              ['반려 사유', String(selected['rejectReason'] ?? '')],
            ]}
          />
        </section>
        {isHr && status === '신청' && (
          <section className="box">
            <h2>검토</h2>
            <ReviewForm
              role={role}
              notify={notify}
              requestId={selected['personnelChangeRequestId']}
              onDone={() => {
                setSelected(null);
                list.reload();
              }}
            />
          </section>
        )}
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>인사정보 변경 신청</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setQuery(draft);
          }}
          onReset={() => {
            const empty = { status: '', employeeId: '' };
            setDraft(empty);
            setQuery(empty);
            setPage(0);
          }}
        >
          <Field label="승인 처리 상태">
            <Select value={draft.status} onChange={(v) => setDraft({ ...draft, status: v })} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
          {isHr && (
            <Field label="신청 임직원">
              <LookupSelect table="employee" role={role} value={draft.employeeId} onChange={(v) => setDraft({ ...draft, employeeId: v })} placeholder="전체" />
            </Field>
          )}
        </Filters>
        <Band total={list.data?.total}>
          {role === '임직원' && <button onClick={() => setCreating(true)}>변경 신청</button>}
        </Band>
        {list.error !== '' && <p>{list.error}</p>}
        <DataTable
          rows={list.data?.items ?? []}
          empty="아직 등록한 변경 신청이 없습니다. 임직원이 변경을 신청하면 이곳에 나타납니다."
          onRowClick={(row) => setSelected(row)}
          columns={[
            { key: 'employeeId', label: '신청 임직원', render: (row) => <RefName table="employee" role={role} value={row['employeeId']} /> },
            { key: 'changeItem', label: '변경 항목' },
            { key: 'afterValue', label: '변경 후 값(암호화)' },
            { key: 'requestReason', label: '신청 사유' },
            { key: 'status', label: '승인 처리 상태', render: (row) => <Badge value={row['status']} /> },
          ]}
        />
        <Pager page={page} size={20} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {creating && (
        <CreateDrawer
          role={role}
          notify={notify}
          onClose={() => setCreating(false)}
          onDone={() => {
            setCreating(false);
            list.reload();
          }}
        />
      )}
    </div>
  );
}
